"""Filesystem, git, and role-profile adapters for the state machine runtime."""

from __future__ import annotations

import subprocess
from pathlib import Path
from typing import Callable

from .. import quest_fs
from ..quest_service import FatalInvariantError
from ..quest_types import RoleProfile, StateMachineId, StateMachineState
from .commit_metadata import (
    CommitMetadataValidationError,
    parse_step_commit_message,
    validate_parsed_step_commit,
)
from .machine import ConcreteStateMachine
from .protocols import StateIo, StateMachineDefinition


def find_quest_root_for_machine_dir(state_machine_dir: Path) -> Path | None:
    """Walk parents until a directory contains both ``meta.json`` and ``state_execution_config.yaml``."""
    cur = state_machine_dir.resolve()
    while True:
        if (cur / "state_execution_config.yaml").is_file() and (cur / "meta.json").is_file():
            return cur
        parent = cur.parent
        if parent == cur:
            return None
        cur = parent


class QuestRootRoleProfileResolver:
    """Resolves role profiles from quest-root ``state_execution_config.yaml`` (version 2 only)."""

    def ResolveRoleProfile(self, state_machine_dir: Path, role: str) -> RoleProfile:
        root = find_quest_root_for_machine_dir(state_machine_dir)
        if root is None:
            raise FatalInvariantError(
                f"No quest root (meta.json + state_execution_config.yaml) found "
                f"at or above {state_machine_dir}"
            )
        try:
            version = quest_fs.read_state_execution_config_version(root)
        except (FileNotFoundError, ValueError) as e:
            raise FatalInvariantError(
                f"Cannot read execution config version for quest root {root}: {e}"
            ) from e
        if version != 2:
            raise FatalInvariantError(
                f"state_execution_config.yaml at {root} must be version 2 "
                f"for state machine role resolution (got {version})"
            )
        try:
            profiles = quest_fs.read_execution_config(root)
        except (FileNotFoundError, ValueError) as e:
            raise FatalInvariantError(
                f"Cannot read execution config at {root}: {e}"
            ) from e
        if role not in profiles:
            raise FatalInvariantError(f"Unknown role profile {role!r} in {root}")
        ep = profiles[role]
        return RoleProfile(
            harness=ep.harness.value,
            model=ep.model,
            reasoning_effort=ep.reasoning_effort,
            idle_timeout_seconds=ep.idle_timeout_seconds,
            modify_allow=tuple(ep.modify_allow),
            modify_block=tuple(ep.modify_block),
        )


class FileStateIo:
    """Reads and writes normalized ``state.md`` using :mod:`quest_runner_service.quest_fs`."""

    def __init__(self, top_level_machine_dir: Path) -> None:
        self._top = top_level_machine_dir.resolve()

    def ReadStateMachineState(self, state_machine_dir: Path) -> StateMachineState:
        require_gs = state_machine_dir.resolve() == self._top
        return quest_fs.read_normalized_machine_state(
            state_machine_dir,
            require_global_step=require_gs,
        )

    def WriteStateMachineState(
        self, state_machine_dir: Path, state: StateMachineState
    ) -> None:
        quest_fs.write_normalized_machine_state(state_machine_dir, state)


def _git_checked(repo_root: Path, *git_args: str) -> subprocess.CompletedProcess[str]:
    r = subprocess.run(
        ["git", "-C", str(repo_root), *git_args],
        capture_output=True,
        text=True,
    )
    if r.returncode != 0:
        err = (r.stderr or r.stdout or "").strip()
        raise FatalInvariantError(f"git {' '.join(git_args)} failed: {err}")
    return r


class SubprocessGitOps:
    """Minimal git operations backed by the ``git`` CLI."""

    def IsClean(self, repo_root: Path) -> bool:
        r = _git_checked(repo_root, "status", "--porcelain")
        return not (r.stdout or "").strip()

    def GetHeadSha(self, repo_root: Path) -> str:
        r = _git_checked(repo_root, "rev-parse", "HEAD")
        return r.stdout.strip()

    def StageAll(self, repo_root: Path) -> None:
        _git_checked(repo_root, "add", "-A")

    def HasStagedChanges(self, repo_root: Path) -> bool:
        r = _git_checked(
            repo_root,
            "diff",
            "--cached",
            "--name-only",
        )
        return bool((r.stdout or "").strip())

    def Commit(self, repo_root: Path, message: str) -> str:
        _git_checked(repo_root, "commit", "-m", message)
        return self.GetHeadSha(repo_root)

    def ReadGlobalStep(self, repo_root: Path, state_machine_id: StateMachineId) -> int:
        target = state_machine_id.machine_path.replace("\\", "/")
        r = subprocess.run(
            ["git", "-C", str(repo_root), "log", "-z", "--format=%B"],
            capture_output=True,
            text=True,
        )
        if r.returncode != 0:
            quest_dir = repo_root / target
            hist = quest_fs.read_history(quest_dir / "state_history.md")
            return len(hist)
        for blob in (r.stdout or "").split("\0"):
            if not blob.strip():
                continue
            parsed = parse_step_commit_message(blob)
            if parsed is None:
                continue
            if parsed.metadata.snapshot.machine_path != target:
                continue
            try:
                validate_parsed_step_commit(parsed)
            except CommitMetadataValidationError:
                continue
            return parsed.metadata.global_step
        quest_dir = repo_root / target
        hist = quest_fs.read_history(quest_dir / "state_history.md")
        return len(hist)


class RegistryStateMachineLoader:
    """Maps absolute machine directories to definition factories."""

    def __init__(self, state_io: StateIo) -> None:
        self._state_io = state_io
        self._factories: dict[str, Callable[[Path], StateMachineDefinition]] = {}

    def register(
        self,
        state_machine_dir: Path,
        factory: Callable[[Path], StateMachineDefinition],
    ) -> None:
        self._factories[str(state_machine_dir.resolve())] = factory

    def LoadStateMachine(self, state_machine_dir: Path) -> ConcreteStateMachine:
        key = str(state_machine_dir.resolve())
        fac = self._factories.get(key)
        if fac is None:
            raise KeyError(f"No state machine registered for directory {key}")
        definition = fac(state_machine_dir)
        return ConcreteStateMachine(state_machine_dir, definition, self._state_io)

    def LoadTopStateMachine(self, machine_root_dir: Path) -> ConcreteStateMachine:
        return self.LoadStateMachine(machine_root_dir)

"""Load and validate quest-local workflow configuration directories."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterator

import yaml

from .quest_types import HarnessKind

_PACKAGED_DEFAULT_WORKFLOW_DIR = (
    Path(__file__).resolve().parent / "default_workflow"
)

_THREAD_SCOPES = frozenset({"quest", "child", "machine", "node"})
_CHILD_RUN_MODES = frozenset({"one_step"})
_COLLECTION_ORDERS = frozenset({"lexical"})
_COLLECTION_ID_FROM = frozenset({"directory_name"})


class WorkflowValidationError(Exception):
    """Raised when workflow YAML fails structural or cross-reference validation."""

    def __init__(
        self,
        message: str,
        *,
        file: str | None = None,
        field_path: str | None = None,
    ) -> None:
        parts: list[str] = []
        if file:
            parts.append(f"file {file}")
        if field_path:
            parts.append(f"field {field_path}")
        prefix = f"({' '.join(parts)}) " if parts else ""
        super().__init__(f"{prefix}{message}")
        self.file = file
        self.field_path = field_path


@dataclass(frozen=True)
class WorkflowSpecial:
    completed_state: str
    human_intervention_file: str


@dataclass(frozen=True)
class WorkflowIssueDeclaration:
    alias: str
    path: str
    owner: str
    id_prefix: str | None = None


@dataclass(frozen=True)
class WorkflowCollection:
    name: str
    path: str
    machine: str
    order: str
    id_from: str
    active_var: str
    scaffold: list[Any]


@dataclass(frozen=True)
class WorkflowProfile:
    name: str
    source_path: Path
    harness: str
    model: str
    reasoning_effort: str | None
    idle_timeout_seconds: int
    prompt: str
    runtime_context: dict[str, bool]
    modify_allow: list[str]
    modify_block: list[str]
    thread_scope: str
    thread_name_template: str
    thread_registry_key_template: str


@dataclass(frozen=True)
class WorkflowState:
    name: str
    node_name: str | None
    persisted_as: str | None
    actions: list[Any]
    run: dict[str, Any] | None
    child: dict[str, Any] | None
    transitions: list[Any]
    terminal: bool


@dataclass(frozen=True)
class WorkflowMachine:
    key: str
    source_path: Path
    machine: str
    initial: str
    terminal: list[str]
    states: dict[str, WorkflowState]


@dataclass
class WorkflowDefinition:
    workflow_dir: Path
    version: int
    name: str
    entry_machine: str
    special: WorkflowSpecial
    preamble: str | None
    variables: dict[str, str]
    scaffold: list[Any]
    collections: dict[str, WorkflowCollection]
    issues: dict[str, WorkflowIssueDeclaration]
    machines: dict[str, WorkflowMachine]
    profiles: dict[str, WorkflowProfile]

    def get_machine(self, key: str) -> WorkflowMachine:
        try:
            return self.machines[key]
        except KeyError as e:
            raise KeyError(f"Unknown machine {key!r}") from e

    def get_profile(self, key: str) -> WorkflowProfile:
        try:
            return self.profiles[key]
        except KeyError as e:
            raise KeyError(f"Unknown profile {key!r}") from e

    def resolve_profile_prompt_path(self, profile_key: str) -> Path:
        profile = self.get_profile(profile_key)
        return (profile.source_path.parent / profile.prompt).resolve()

    def issue_declarations(self) -> list[WorkflowIssueDeclaration]:
        return list(self.issues.values())

    def collection_by_active_var(self, active_var: str) -> WorkflowCollection | None:
        for collection in self.collections.values():
            if collection.active_var == active_var:
                return collection
        return None

    def collection_by_path_pattern(self, path_pattern: str) -> WorkflowCollection | None:
        for collection in self.collections.values():
            if collection.path == path_pattern:
                return collection
        return None


def load_packaged_default_workflow() -> WorkflowDefinition:
    """Load the packaged default workflow directory shipped with quest-runner."""
    return load_workflow(_PACKAGED_DEFAULT_WORKFLOW_DIR)


def load_workflow(workflow_dir: Path) -> WorkflowDefinition:
    """Load and validate a workflow directory."""
    workflow_dir = workflow_dir.resolve()
    workflow_path = workflow_dir / "workflow.yaml"
    if not workflow_path.is_file():
        raise WorkflowValidationError(
            "missing workflow.yaml",
            file=str(workflow_path),
        )
    raw_any = yaml.safe_load(workflow_path.read_text(encoding="utf-8"))
    if not isinstance(raw_any, dict):
        raise WorkflowValidationError(
            "workflow.yaml must be a mapping",
            file=str(workflow_path),
        )
    raw: dict[str, Any] = raw_any
    return _parse_workflow(workflow_dir, workflow_path, raw)


def _validation_error(
    message: str,
    *,
    file: str | Path | None = None,
    field_path: str | None = None,
) -> WorkflowValidationError:
    file_str = str(file) if file is not None else None
    return WorkflowValidationError(message, file=file_str, field_path=field_path)


def _require_mapping(
    value: Any,
    *,
    file: Path,
    field_path: str,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise _validation_error(
            f"{field_path} must be a mapping, got {type(value).__name__}",
            file=file,
            field_path=field_path,
        )
    return value


def _require_str(
    value: Any,
    *,
    file: Path,
    field_path: str,
) -> str:
    if not isinstance(value, str) or not value:
        raise _validation_error(
            f"{field_path} must be a non-empty string",
            file=file,
            field_path=field_path,
        )
    return value


def _require_int(
    value: Any,
    *,
    file: Path,
    field_path: str,
) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise _validation_error(
            f"{field_path} must be an integer",
            file=file,
            field_path=field_path,
        )
    return value


def _require_list(
    value: Any,
    *,
    file: Path,
    field_path: str,
) -> list[Any]:
    if not isinstance(value, list):
        raise _validation_error(
            f"{field_path} must be a list",
            file=file,
            field_path=field_path,
        )
    return value


def _resolve_workflow_relative(workflow_dir: Path, rel_path: str) -> Path:
    return (workflow_dir / rel_path).resolve()

"""Quest and slice machine nodes for the canonical recursive runner."""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

from .. import quest_fs
from ..harness import create_harness
from ..quest_runner import (
    _get_slice_dir,
    git_rev_parse_head,
    perform_role_harness_sequence,
    role_thread_key,
    scaffold_slice_dir,
)
from .quest_v2_predicates import (
    physical_planning_next_state,
    prepare_next_slice_transition,
    quest_documenting_next_state,
    review_physical_plan_next_state,
    slice_implementing_next_state,
    slice_polishing_review_next_state,
)
from ..quest_thread import load_thread, resolve_or_create_thread_spec
from ..quest_types import QuestState, RecursiveSnapshot, SliceState
from .base_node import BaseNode
from .context import RunContext
from .machine import ConcreteStateMachine

if TYPE_CHECKING:
    from .protocols import StateMachine


class PrePlanningGateNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "PrePlanning"


class CompletedGateNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Completed"


class _ThreadLlmNode(BaseNode):
    m_role: str

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        assert ctx.captured_outputs_list is not None
        assert ctx.role_step_seq_box is not None
        if ctx.harness_steps_acc is not None:
            ctx.harness_steps_acc[0] += 1
        quest_dir = ctx.machine_root_dir
        qsi = quest_fs.read_quest_state(quest_dir)
        slice_dir: Path | None = None
        slice_state: SliceState | None = None
        if qsi.state == QuestState.ExecuteSlice and qsi.current_slice is not None:
            slice_dir = _get_slice_dir(quest_dir, qsi.current_slice)
            slice_state = quest_fs.read_slice_state(slice_dir).state
        meta = quest_fs.read_quest_meta(quest_dir)
        profiles = quest_fs.read_execution_config(quest_dir)
        harness_configs = quest_fs.read_harness_configs(quest_dir)
        profile = profiles[self.m_role]
        harness = create_harness(
            profile.harness, harness_configs.get(profile.harness.value)
        )
        quest_rel = quest_dir.resolve().relative_to(ctx.repo_root.resolve()).as_posix()
        slice_rel: str | None = None
        if slice_dir is not None:
            slice_rel = slice_dir.resolve().relative_to(ctx.repo_root.resolve()).as_posix()
        step_base = git_rev_parse_head(ctx.repo_root)
        thread_key = role_thread_key(self.m_role, slice_dir)
        thread_box: list = [
            load_thread(quest_dir, ctx.repo_root, self.m_role, registry_key=thread_key)
        ]
        assert ctx.conductor_repo_path is not None
        assert ctx.quest_docs_dir is not None
        assert ctx.role_step_seq_box is not None
        snum = qsi.current_slice if qsi.state == QuestState.ExecuteSlice else None

        def _create() -> object:
            return resolve_or_create_thread_spec(
                quest_dir,
                ctx.repo_root,
                self.m_role,
                harness,
                meta.quest_number,
                profile.model,
                profile.reasoning_effort,
                profile.idle_timeout_seconds,
                snum,
                registry_key=thread_key,
            )

        perform_role_harness_sequence(
            repo_path=ctx.repo_root,
            quest_dir=quest_dir,
            conductor_repo_path=ctx.conductor_repo_path,
            meta=meta,
            quest_docs_dir=ctx.quest_docs_dir,
            quest_state_info=qsi,
            slice_dir=slice_dir,
            slice_state=slice_state,
            profile=profile,
            harness=harness,
            role_name=self.m_role,
            thread_key=thread_key,
            quest_rel=quest_rel,
            slice_rel=slice_rel,
            step_base_commit=step_base,
            thread_box=thread_box,
            role_step_seq=ctx.role_step_seq_box,
            captured_outputs=ctx.captured_outputs_list,
            create_thread_if_missing=_create,
            event_bus=ctx.event_bus,
            experiment_id=ctx.experiment_id,
        )

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        raise NotImplementedError


class PhysicalPlanningNode(_ThreadLlmNode):
    m_role = "physical_planner"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return physical_planning_next_state(ctx.machine_root_dir)
        except Exception:
            return "PhysicalPlanning"


class ReviewPhysicalPlanNode(_ThreadLlmNode):
    m_role = "physical_plan_reviewer"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return review_physical_plan_next_state(ctx.machine_root_dir)
        except Exception:
            return "ReviewPhysicalPlan"


class PrepareNextSliceNode(BaseNode):
    def __init__(self) -> None:
        self._picked = ""

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        return None

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        nxt, tags = prepare_next_slice_transition(ctx.machine_root_dir)
        self._picked = tags.get("active_slice", "")
        return nxt

    def NodeTags(self, ctx: RunContext, machine: StateMachine) -> dict[str, str]:
        if self._picked:
            return {"active_slice": self._picked}
        return {}


class ExecuteActiveSliceNode(BaseNode):
    m_child_snapshot: object | None

    def __init__(self) -> None:
        self.m_child_snapshot = None

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        quest_dir = ctx.machine_root_dir
        top = quest_fs.read_quest_state(quest_dir)
        active = top.active_slice
        if not active:
            raise RuntimeError("ExecuteActiveSliceNode: missing active_slice")
        slice_dir = quest_dir / "slices" / active
        if not slice_dir.is_dir():
            raise RuntimeError(f"ExecuteActiveSliceNode: missing {slice_dir}")
        child = ctx.state_machine_loader.LoadStateMachine(slice_dir)
        assert isinstance(child, ConcreteStateMachine)
        self.m_child_snapshot = child.RunOneStep(ctx)

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        if self.m_child_snapshot is None:
            raise RuntimeError("child snapshot missing")
        snap: RecursiveSnapshot = self.m_child_snapshot
        if snap.state_after == "Completed":
            return "PrepareNextSlice"
        return "ExecuteSlice"

    def PopChildRecursiveSnapshot(self) -> object | None:
        c = self.m_child_snapshot
        self.m_child_snapshot = None
        return c


class QuestDocumentingNode(_ThreadLlmNode):
    m_role = "documenter"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        box = ctx.documenter_base_ref_box
        if box is None:
            return "QuestDocumenting"
        ref = box[0]
        if not ref:
            return "QuestDocumenting"
        try:
            return quest_documenting_next_state(
                repo_path=ctx.repo_root,
                quest_dir=ctx.machine_root_dir,
                meta=quest_fs.read_quest_meta(ctx.machine_root_dir),
                documenter_base_ref=ref,
            )
        except Exception:
            return "QuestDocumenting"


class SliceSetupNode(BaseNode):
    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        scaffold_slice_dir(machine.StateMachineDir())

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        return "Implementing"


class SliceImplementingNode(_ThreadLlmNode):
    m_role = "implementer"

    def Execute(self, ctx: RunContext, machine: StateMachine) -> None:
        self._step_base = git_rev_parse_head(ctx.repo_root)
        super().Execute(ctx, machine)

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return slice_implementing_next_state(machine.StateMachineDir())
        except Exception:
            return "Implementing"


class SlicePolishingReviewNode(_ThreadLlmNode):
    m_role = "polisher_reviewer"

    def NextState(self, ctx: RunContext, machine: StateMachine) -> str:
        try:
            return slice_polishing_review_next_state(machine.StateMachineDir())
        except Exception:
            return "PolishingReview"

        if slice_state is None:
            fatal_invariant("ExecuteSlice requires a slice_state for role resolution")
        key: tuple[QuestState, SliceState | None] = (quest_state, slice_state)
    else:
        key = (quest_state, None)
    role = _ROLE_MAP.get(key)
    if role is None:
        fatal_invariant(
            f"No role mapping for quest_state={quest_state!r} slice_state={slice_state!r}"
        )
    return role


def _quest_key(meta: QuestMeta) -> str:
    return f"{meta.quest_type}/{meta.quest_number:04d}_{meta.quest_slug}"


def quest_has_open_physicalplan_issues(quest_dir: Path) -> bool:
    issues = quest_fs.read_issues(quest_dir / "physicalplan_issues.md")
    return any(i.status.strip().lower() == "open" for i in issues)


def slice_has_open_polishing_issues(slice_dir: Path) -> bool:
    issues = quest_fs.read_issues(slice_dir / "polishing_issues.md")
    return any(i.status.strip().lower() == "open" for i in issues)


def all_required_slice_plan_files_exist(quest_dir: Path) -> bool:
    slice_dirs = quest_fs.list_slice_dirs(quest_dir)
    if not slice_dirs:
        return False
    for slice_dir in slice_dirs:
        pp = slice_dir / "physicalplan"
        if not pp.is_dir():
            return False
        md_files = list(pp.glob("*.md"))
        if not md_files:
            return False
        for rel in ("state.md", "state_history.md", "polishing_issues.md"):
            if not (slice_dir / rel).is_file():
                return False
    return True


def implementer_done_signal(slice_dir: Path, repo_path: Path, previous_commit: str) -> bool:
    _ = repo_path, previous_commit
    return (slice_dir / _IMPLEMENTATION_DONE_FILE).is_file()


def physical_plan_review_done_signal(quest_dir: Path) -> bool:
    return not quest_has_open_physicalplan_issues(quest_dir) and (
        quest_dir / _PHYSICAL_PLAN_ACCEPTED_FILE
    ).is_file()


def implementation_review_done_signal(slice_dir: Path) -> bool:
    return not slice_has_open_polishing_issues(slice_dir) and (
        slice_dir / _IMPLEMENTATION_ACCEPTED_FILE
    ).is_file()


def docs_updated_for_quest(repo_path: Path, base_ref: str, project_docs_rel: str) -> bool:
    if not base_ref:
        return False
    docs_rel = _normalize_repo_relative_path(project_docs_rel)
    checks: list[list[str]] = [
        ["diff", "--name-only", base_ref, "HEAD", "--", docs_rel],
        ["diff", "--name-only", base_ref, "--", docs_rel],
        ["ls-files", "--others", "--exclude-standard", "--", docs_rel],
    ]
    for args in checks:
        proc = subprocess.run(
            ["git", "-C", str(repo_path), *args],
            capture_output=True,
            text=True,
        )
        if proc.returncode == 0 and any(x.strip() for x in proc.stdout.splitlines()):
            return True
    return False


def build_task_instruction(
    quest_state: QuestState,
    slice_state: SliceState | None,
    quest_dir: Path,
    slice_dir: Path | None,
    project_docs_rel: str | None = None,
) -> str:
    if quest_state == QuestState.PhysicalPlanning:
        if quest_has_open_physicalplan_issues(quest_dir):
            return (
                "Address the open physical-plan issues. Use "
                "`scripts/quest-runner issues list --scope physicalplan` to read them. "
                "Update the physical plans and related slice scaffolding as needed, then "
                "record per-issue responses with "
                "`scripts/quest-runner issues respond <id> --scope physicalplan "
                "--outcome Fixed|NotFixed --explanation \"...\"`."
            )
        return (
            "Read the specs in `specs/`, decide the full ordered slice list and "
            "slugs, then initialize slice directories with "
            "`scripts/quest-runner slices init --project <project> --type <main|side> "
            "--number <n> --count <count> --slug <slug> ...`. After initialization, "
            "write at least one `.md` plan file under each slice's `physicalplan/` "
            "directory."
        )
    if quest_state == QuestState.ReviewPhysicalPlan:
        return (
            "Review the physical plans in all slices. Use "
            "`scripts/quest-runner issues create` and `issues edit` with "
            "`--scope physicalplan` to report or close issues. Reviewers close resolved "
            "issues with `issues edit <id> --status completed`. "
            "If you finish with no open issues, create `physicalplan_accepted.md` "
            "with a brief acceptance summary."
        )
    if quest_state == QuestState.ExecuteSlice and slice_state == SliceState.Implementing:
        assert slice_dir is not None
        rel = slice_dir.name
        return (
            f"Implement the plan described in `{rel}/physicalplan/`. Keep "
            "working until the full plan is complete. "
            f"When the full plan is complete, create `{_IMPLEMENTATION_DONE_FILE}` "
            "in this slice with a brief completion summary."
        )
    if quest_state == QuestState.ExecuteSlice and slice_state == SliceState.PolishingReview:
        return (
            "Review the implementation in this slice. Use "
            "`scripts/quest-runner issues create` and `issues edit` with "
            "`--scope polishing --slice <n>` to report or close issues. Reviewers close "
            "resolved issues with `issues edit <id> --status completed`. "
            "If you finish with no open issues, create `implementation_accepted.md` "
            "in this slice with a brief acceptance summary."
        )
    if quest_state == QuestState.ExecuteSlice and slice_state == SliceState.PolishingFix:
        return (
            "Fix the open polishing issues for this slice. Use "
            "`scripts/quest-runner issues list --scope polishing --slice <n>` to read them. "
            "Record responses with `scripts/quest-runner issues respond <id> "
            "--scope polishing --slice <n> --outcome Fixed|NotFixed --explanation \"...\"`. "
            "Do not close issues yourself."
        )
    if quest_state == QuestState.QuestDocumenting:
        docs_rel = project_docs_rel or "$currentProject/docs"
        return (
            f"Write documentation in `{docs_rel}/` describing what was built "
            "across the full quest. Do not modify repo-root `docs/` unless it "
            "is the current project's docs directory."
        )
    fatal_invariant(
        f"build_task_instruction: unsupported state {quest_state!r} / {slice_state!r}"
    )


_SLICE_SCOPED_THREAD_ROLES = {"implementer", "polisher", "polisher_reviewer"}


def role_thread_key(role_name: str, slice_dir: Path | None) -> str:
    if role_name in _SLICE_SCOPED_THREAD_ROLES and slice_dir is not None:
        idx = slice_index_from_dirname(slice_dir.name)
        if idx is None:
            fatal_invariant(f"invalid slice directory name for thread key: {slice_dir.name}")
        return f"slice_{idx}_{role_name}"
    return role_name


def _parse_iso(ts: str | None) -> datetime | None:
    if not ts:
        return None
    try:
        return datetime.fromisoformat(ts.replace("Z", "+00:00"))
    except ValueError:
        return None


def _hashes_for_threads_since(
    repo_path: Path, thread_names: set[str], since_ts: str | None
) -> list[str]:
    if not thread_names:
        return []
    cmd = ["git", "-C", str(repo_path), "log", "--pretty=%H%x09%s"]
    if since_ts:
        cmd.extend(["--since", since_ts])
    proc = subprocess.run(cmd, capture_output=True, text=True)
    if proc.returncode != 0:
        return []
    out: list[str] = []
    for line in proc.stdout.splitlines():
        commit, _, subject = line.partition("\t")
        if not commit:
            continue
        for tn in thread_names:
            if f" via {tn}" in subject:
                out.append(commit)
                break
    return out


def reviewer_commit_context(
    *,
    repo_path: Path,
    quest_dir: Path,
    role_name: str,
    thread_key: str,
    slice_dir: Path | None,
) -> str:
    if role_name not in {"physical_plan_reviewer", "polisher_reviewer"}:
        return ""
    registry = quest_fs.read_thread_registry(quest_dir)
    reviewer_entry = registry.get(thread_key)
    reviewer_last_used = None
    reviewer_round_count = 0
    if isinstance(reviewer_entry, dict):
        reviewer_last_used = str(reviewer_entry.get("last_used_at") or "").strip() or None
        try:
            reviewer_round_count = int(reviewer_entry.get("round_count", 0))
        except (TypeError, ValueError):
            reviewer_round_count = 0
    source_keys: list[str]
    if role_name == "physical_plan_reviewer":
        source_keys = ["physical_planner"]
    else:
        if reviewer_round_count <= 0:
            source_keys = [role_thread_key("implementer", slice_dir)]
        else:
            source_keys = [role_thread_key("polisher", slice_dir)]

    thread_names: set[str] = set()
    for k in source_keys:
        entry = registry.get(k)
        if isinstance(entry, dict):
            tn = str(entry.get("thread_name") or "").strip()
            if tn:
                thread_names.add(tn)
    hashes = _hashes_for_threads_since(repo_path, thread_names, reviewer_last_used)
    if hashes:
        lines = "\n".join(f"- `{h}`" for h in hashes)
    else:
        lines = "- (none found)"
    return f"\n\nRelevant commit hashes for this review:\n{lines}"


